["heist_short1_stage1"] = "Stealth - Flash Drive",
["heist_short1_stage1_briefing"] = "Dallas, eski dostum, iki yıl sonra döndüğüne sevindim. Titiz bir adam olduğumu biliyorsun; pasını atmanı istemem şaşırtıcı olmamalı. Eski günlerdeki gibi yönergelerimi izle; çocuk oyuncağı olacak. Sonra ihtiyacımız olacak erişim şifrelerinin peşindeyiz ama basit bir soygun gibi görünmeli. Bu işi sessizce yapacaksın; ona göre giyin.",
["heist_short1_stage1_crimenet"] = "Polislerin depo tesisine gir ve daha sonra ihtiyacımız olacak erişim kodlarını ele geçir.",
["heist_short1_stage1_hl"] = "Stealth - Flash Drive",
["heist_short1_stage2"] = "Stealth - Erasing History",
["heist_short1_stage2_briefing"] = "Pekâlâ Dallas. Dün gece çaldığımız erişim şifrelerini kullanma zamanı. Binaya girmenin bir yolunu bul; polis veri tabanına eriş ve Crime.net hakkında ellerindeki tüm istihbaratı sil. Çocuk oyuncağı olmayacak; gereken yeteneğe hâlâ sahip olduğunu göster.",
["heist_short1_stage2_crimenet"] = "Binaya zorla gir; polis veri tabanına eriş ve Crime.net hakkında ellerindeki tüm istihbaratı sil.",
["heist_short1_stage2_hl"] = "Stealth - Erasing History",
