["heist_short2_plan_nx64"] = "Çatışma",
["heist_short2_stage1"] = "Loud - Get The Coke",
["heist_short2_stage1_briefing"] = "Tamam Dallas. Birlikte çalışalı iki yıl oldu; hâlâ gereken yeteneğe sahip olduğunu görmeliyim. Basit bir işle başlayacağız, tamam mı? Bir tanıdığım geçenlerde kokain alışverişinde aşağılık bir mafyacı tarafından soyuldu. Gece kulübüne girip çalınan kokaini bulmanı ve geri almanı istiyorum. Kolay, değil mi? ",
["heist_short2_stage1_crimenet"] = "Tamam Dallas. Birlikte çalışmayalı iki yıl oldu. Sende hâlâ o becerinin olduğunu görmem gerekiyor. Basit bir şeyle başlayalım, olur mu? Bir tanıdığım geçenlerde kokain alışverişinde aşağılık bir mafya herifine soyulmuş. Gece kulübüne girip çalınan kokaini bulmaya ve geri almaya çalışmanı istiyorum. Kolay, değil mi?",
