["heist_type_knockover"] = "Knockover",
["heist_type_trade"] = "Trade",
["heist_ukrainian_job"] = "Ukrainian Job",
["heist_ukrainian_job_briefing"] = "Vlad şu Dmitri denen adamdan gerçekten hoşlanmıyor. Eski memleketten kalma kan davalarından biri. Belki kız kardeşiyle falan yatmıştır. Her neyse, adamın hesabı kapatmasına yardım edelim. Tacın peşindeyiz; anladığım kadarıyla arka odada. Polisi çok erken peşinize takmayın, yoksa kaçışınız zorlaşır. Desteklerinizi kontrol edin. Hadi gidelim.",
["heist_ukrainian_job_crimenet"] = "Vlad'ın, onu hapse gönderen sıçanın düğününü mahvetmesine yardım et.$NL;$NL;» Kuyumcuyu bul$NL;» Tacı bul ve çal$NL;» Bulduğun diğer değerli eşyaları çal",
["heist_ukrainian_job_hl"] = "Ukrainian Job",
["heist_vit"] = "The White House",
["heist_vit_briefing"] = "Başlıyoruz sevgili dostlar. Aradığımız af belgeleri büyük olasılıkla White House'un altındaki Presidential Emergency Operations Center'da, yani PEOC'ta tutuluyor. Kesin ayrıntıları alamadım; güvenliği ciddi biçimde yükseltmişler gibi görünüyor. Duruma göre hareket edeceğiz. Sizi bizzat uçuracağım; biraz uyum sağlamak için Murky üniforması giyeceksiniz. Yapabilirseniz sessizce girin, gerçekten gerekirse açık çatışmaya geçin. Bu iş Bain için. Belki bizim için de, değil mi?",
["heist_vit_crimenet"] = "Tüm soygunların en büyüğü. Bunun için eğitim gördünüz. Lanet White House! Bütün sorunlarımızın cevabı içeride. Cevabın önemli bir parçası da bir dizi belge: hâlâ yasal ve geçerli ama üstlerinde hiç isim olmayan başkanlık af belgeleri! Alabilirseniz hiçbir ceza almadan kurtulup emekli olabilirsiniz.$NL;$NL;» White House'a gir$NL;» Oval Ofis'e gir$NL;» Başkanın Anahtar Kartını al$NL;» PEOC'a gir ve kasa dairesini aç$NL;» Başkanlık af belgelerini çal ve kaç",
["heist_vit_crimenet_hl"] = "The White House",
["heist_vit_hl"] = "The White House",
["heist_watchdogs"] = "Watchdogs",
["heist_watchdogs_1_briefing"] = "Bu işte bekçilik yapıyoruz.$NL;$NL;Sağlam bir ceket giyin ve daha da sağlam silahlar getirin. Hector'ın sevkiyatlarına saldırıldığını biliyoruz. Kamyonun arkasında gideceksiniz. Kokainin hiçbir yere kaybolmasına izin vermeyin.",
["heist_watchdogs_1_hl"] = "Truck Load",
["heist_watchdogs_2_briefing"] = "Tamam, planladığımız gibi limana gidin. Kokaini pikaptan indirin. Hector'ın teknesinin yanaşması için depodan işaret vermeniz gerekecek. Tekne geldiğinde kokaini güverteye taşıyın. Gerisini kaptan halleder.",
["heist_watchdogs_2_hl"] = "Boat Load",
["heist_watchdogs_crimenet"] = "Hector, kokain sevkiyatına göz kulak olacak adamlara ihtiyaç duyuyor.$NL;$NL;» Kamyondaki kokaini koru$NL;» Değişen durumlara uyum sağla$NL;» Limana ulaş$NL;» Sevkiyatı tekne kaptanına teslim et",
["heist_welcome_to_the_jungle"] = "Big Oil",
["heist_welcome_to_the_jungle_1_briefing"] = "The Elephant, bilim insanının küçük cihazını arayan motorcu çetesinin yerini verdi. Bence adamı bulmaya çok yaklaştılar. Ondan önce davranmak için ellerindeki istihbarata ihtiyacımız var. Bahse girerim kasalarındadır.",
["heist_welcome_to_the_jungle_1_hl"] = "Club House",
["heist_welcome_to_the_jungle_2_briefing"] = "İstihbaratı inceledim. Bu iş ilginç olacak. Destek seçeneklerine bakın ve hepsini iyice öğrenin. Bu adamın laboratuvarını, laboratuvarda da füzyon motorunu bulmak için içeri gizlice girmemiz gerekiyor.",
["heist_welcome_to_the_jungle_2_hl"] = "Engine Problem",
["heist_welcome_to_the_jungle_crimenet"] = "The Elephant, siyasi dengeleri bozabilecek bir icadın halledilmesini istiyor.$NL;$NL;» Mucit hakkında daha fazla bilgi edin$NL;» İcadı bul ve çal",
["heist_wwh"] = "Alaskan Deal",
["heist_wwh_briefing"] = "Locke, Alaska'daki bir silah alışverişini korumak için yardım istedi. Sorun beklemediğini söylüyor ama ne olur ne olmaz diye güvenilir güvenlik istiyormuş. Soğuğa dayanabilirseniz kolay bir kazanç gibi görünüyor.",
["heist_wwh_crimenet"] = "Sevgili dostlar, biraz silah elden çıkarmak için yardıma ihtiyacım var. Alaska'da bir anlaşma ayarladım ama alışverişin güvenliğini sağlamak için bana eşlik etmelisiniz, tamam mı?",
["heist_wwh_hl"] = "Alaskan Deal",
["houston_desc_codex"] = "Dallas'ın küçük kardeşi Hoxton maskesini tutabilir ama adı tutamayacak. Payday Gang'in ortak kararı, bundan böyle New Hoxton'ın Houston lakabıyla anılması. Hoxton'ı sakinleştirmek ve onu hapiste bıraktıkları için PAYDAY Gang'i kısmen de olsa affetmesini sağlamak adına oldukça küçük bir bedel.",
["hud_assault_survived"] = "WAVE SURVIVED",
["job_mex"] = "Border Crossing",
["job_mex_cooking"] = "Border Crystals",
["jowi_desc_codex"] = "John, en büyük suç örgütlerinden bazılarının tanıdığı, korkulan bir tetikçiydi. Uzun süre ortadan kaybolduktan sonra yakın zamanda yeniden ortaya çıktı ve Chains'i hassas bir durumdan kurtardı. Karşılığında John, Chains'e bir ekibe ihtiyacı olduğunu söyledi. Chains nasıl hayır diyebilirdi? Eski dostuna yardım etmek için onu Payday Gang'e davet etti. ",
["message_got_chavez_keys"] = "Chavez'in anahtarları alındı!",
["rb14_drk_cbf_01_01"] = "EMP bombasını ele geçirmek için lanet Murkywater'la uğraşmamız gerekecek. Trenle bir sürü mal taşıyorlar ve gizli bir tren sahasında planlı mola verecekler. Ben tabii silahları konuşturmayı tercih ederim ama bu fazla riskli, değil mi? O yüzden bunu gizlice yapmalıyız çocuklar.$NL;$NL;» Trenleri bul$NL;» EMP bombası parçalarını bul$NL;» Parçaları oradan çıkar ve kaç",
["rb14_drk_outro_01_01"] = "İpek gibi pürüzsüzdü kızlar ve oğlanlar! EMP bombası güvende; gizli tesise girmek için gereken artık elimizde. Rusya Ana, işte geliyoruz! ",
["rb14_drk_outro_01_02"] = "Harika oldu be çocuklar! EMP bombası güvende olduğuna göre yeraltı tesisine girebiliriz. Lanet Rusya'ya gitme zamanı!",
["rb14_drk_outro_02_01"] = "Siktir, alarm çaldı ama başardık. İyiyiz. O lanet Murky'ler neye uğradıklarını anlamayacak. Akan ise kuduracak. Bunu düşünmek hoşuma gidiyor. ",
["rb14_mad_cbf_01_01"] = "Bu pis Rus örgütü, Rusya'daki gizli bir laboratuvarda çok rahatsız edici deneyler yürütüyor. Orada ne boklar yaptıklarına inanamazsınız. Akan'ın verilere ulaşmasını kesinlikle engellemeliyiz, tamam mı? Ya başarırız ya ölürüz kızlar ve oğlanlar.$NL;$NL;» Yerleşkeye gir$NL;» Laboratuvara eriş$NL;» Verileri al$NL;» Kaç",
["rb14_mad_outro_01_01"] = "Başardık be çocuklar! O beyaz saçlı ucubenin istediği verileri almasını engelledik. Ne dersiniz? Ne dersiniz? Yakalım mı? Yakıp cehennemin dibine gönderelim!",
["russian_desc_codex"] = "Dallas deneyimli, kurnaz ve sistemlidir. Ekibin parçası olarak çalışmakta sorun yaşamaz ama pek sosyal değildir. Bir plandaki görevini kusursuz yerine getirir ve herkesten aynısını bekler. ",
["spanish_desc_codex"] = "Chains, gençliğinde sürekli başını belaya sokardı. Yıllarca koruyucu ailelerle çocuk ıslahevleri arasında gidip geldikten sonra orduya girdi. Orada mükemmel bir asker oldu.",
}
